def family_init(ctx):
    """CLV = ((C-L)-(H-C))/(H-L): +1 closing on the high, -1 on the low.
    A run of strong closes that produces NO net price change, on wide and
    heavy bars, is the absorption signature. The two constraints together --
    strong closes AND flat price -- are what separate this from momentum."""
    import indicators as I
    bars = ctx.bars
    m = len(bars)
    r = max(2, int(ctx.p.run_n))
    h = [float(b["h"]) for b in bars]
    l = [float(b["l"]) for b in bars]
    c = [float(b["c"]) for b in bars]
    vv = [float(b.get("v") or 0.0) for b in bars]
    at = I.compute("atr", bars, period=int(ctx.p.atr_n))["atr"]

    clv = [0.0] * m
    for i in range(m):
        rg = h[i] - l[i]
        clv[i] = 0.0 if rg <= 0.0 else ((c[i] - l[i]) - (h[i] - c[i])) / rg

    nv = max(2, int(ctx.p.vol_n))
    av = [None] * m
    s = 0.0
    for i in range(m):
        s += vv[i]
        if i >= nv:
            s -= vv[i - nv]
        if i >= nv - 1:
            av[i] = s / nv

    th = [None] * m        # long buy-stop trigger armed on this bar
    tl = [None] * m        # short sell-stop trigger
    ph = [None] * m        # protective level for a long  (setup low)
    pl = [None] * m        # protective level for a short (setup high)
    cm = float(ctx.p.clv_mean)
    cn = float(ctx.p.clv_min)
    for i in range(r, m):
        a = at[i]
        if a is None or a <= 0.0 or av[i] is None or av[i] <= 0.0:
            continue
        if abs(c[i] - c[i - r]) > ctx.p.net_atr * a:
            continue                       # net progress must be ~zero
        rs = 0.0
        vs = 0.0
        for j in range(i - r + 1, i + 1):
            rs += h[j] - l[j]
            vs += vv[j]
        if rs < ctx.p.rng_atr * a:
            continue                       # the bars were not quiet
        if vs < ctx.p.vol_mult * r * av[i]:
            continue                       # the trade was heavy
        w = clv[i - r + 1:i + 1]
        mean = sum(w) / r
        if mean >= cm and min(w) >= cn:
            th[i] = max(h[i - r + 1:i + 1])
            ph[i] = min(l[i - r + 1:i + 1])
        elif mean <= -cm and max(w) <= -cn:
            tl[i] = min(l[i - r + 1:i + 1])
            pl[i] = max(h[i - r + 1:i + 1])

    ctx.th = ctx.series(th, "trigger_long")
    ctx.tl = ctx.series(tl, "trigger_short")
    ctx.ph = ctx.series(ph, "setup_low")
    ctx.pl = ctx.series(pl, "setup_high")
    ctx.clv = ctx.series(clv, "clv")
    ctx._prot = None


def signal(ctx, i):
    """The stop order left above the run: it triggers when a later bar trades
    through the run's extreme. Valid for `valid` bars, then the setup lapses."""
    tick = float(ctx.p.tick)
    for k in range(1, max(1, int(ctx.p.valid)) + 1):
        j = i - k
        if j < 0:
            break
        t = ctx.th[j]
        if t is not None and ctx.h[i] >= t + tick:
            if not ctx.positions:
                ctx._prot = ctx.ph[j]
            return 1
        t = ctx.tl[j]
        if t is not None and ctx.l[i] <= t - tick:
            if not ctx.positions:
                ctx._prot = ctx.pl[j]
            return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    d = 1 if ctx.positions[0]["side"] == "long" else -1
    px = ctx.c[i]
    cl = ctx.clv[i]
    if cl is not None:
        # a decisive close on the wrong end reverses the whole premise
        if d > 0 and cl <= -ctx.p.clv_rev:
            return True
        if d < 0 and cl >= ctx.p.clv_rev:
            return True
    p = ctx._prot
    if p is not None:
        if d > 0 and px < p:
            return True
        if d < 0 and px > p:
            return True
    r = max(2, int(ctx.p.run_n))
    if i - r >= 0:
        if d > 0:
            lo = None
            for k in range(1, r + 1):
                x = ctx.l[i - k]
                if x is not None and (lo is None or x < lo):
                    lo = x
            if lo is not None and px < lo:
                return True
        else:
            hi = None
            for k in range(1, r + 1):
                x = ctx.h[i - k]
                if x is not None and (hi is None or x > hi):
                    hi = x
            if hi is not None and px > hi:
                return True
    return False
